#include "x86.hpp"
#include <cstdio>

namespace blitz::recompiler::x86 {
	namespace {
		struct reader {
			std::vector<uint8_t> const& code;
			uint32_t                    start;
			uint32_t                    at;

			uint8_t u8()
			{
				if (at >= code.size()) {
					throw bad_code(start, "instruction runs past the end of the code");
				}
				return code[at++];
			}
			int32_t i8() { return int8_t(u8()); }
			int32_t i32()
			{
				uint32_t v = u8();
				v |= uint32_t(u8()) << 8;
				v |= uint32_t(u8()) << 16;
				v |= uint32_t(u8()) << 24;
				return int32_t(v);
			}
			uint16_t u16()
			{
				uint16_t v = u8();
				v |= uint16_t(u8()) << 8;
				return v;
			}
		};

		operand reg_op(int r, int size = 4)
		{
			operand o;
			o.type = operand::kind::reg;
			o.r    = r;
			o.size = size;
			return o;
		}

		operand imm_op(int32_t v, int pos = -1)
		{
			operand o;
			o.type  = operand::kind::imm;
			o.value = v;
			o.pos   = pos;
			return o;
		}

		// ModRM: returns the register field, and the r/m operand (a register or memory).
		operand modrm(reader& r, int& regfield, int size)
		{
			uint8_t m   = r.u8();
			int     mod = m >> 6, rm = m & 7;
			regfield    = (m >> 3) & 7;
			if (mod == 3) {
				return reg_op(rm, size);
			}
			operand o;
			o.type = operand::kind::mem;
			o.size = size;
			if (rm == 4) {
				uint8_t sib = r.u8();
				o.scale     = 1 << (sib >> 6);
				int idx     = (sib >> 3) & 7;
				int base    = sib & 7;
				o.index     = idx == 4 ? int(NONE) : idx;
				if (base == 5 && mod == 0) {
					o.base = NONE;
					o.pos  = int(r.at);
					o.disp = r.i32();
					return o;
				}
				o.base = base;
			} else if (rm == 5 && mod == 0) {
				o.pos  = int(r.at);
				o.disp = r.i32();
				return o;
			} else {
				o.base = rm;
			}
			if (mod == 1) {
				o.disp = r.i8();
			} else if (mod == 2) {
				o.pos  = int(r.at);
				o.disp = r.i32();
			}
			return o;
		}

		op alu(int n)
		{
			static const op table[8] = { op::ADD, op::OR, op::ADC, op::SBB, op::AND, op::SUB, op::XOR, op::CMP };
			return table[n];
		}
	} // namespace

	insn decode(std::vector<uint8_t> const& code, uint32_t address)
	{
		reader r{ code, address, address };
		insn   i;
		i.address = address;
		auto bad  = [&](char const* why) -> bad_code {
            char buffer[96];
            std::snprintf(buffer, sizeof(buffer), "%s (opcode %02x at %08x)", why, address < code.size() ? code[address] : 0, address);
            return bad_code(address, buffer);
		};
		int     rf;
		uint8_t b = r.u8();

		if (b < 0x40 && (b & 7) < 6) {
			// The arithmetic group: add or adc sbb and sub xor cmp, in the forms that take 32 bit operands.
			i.code = alu(b >> 3);
			switch (b & 7) {
			case 1: // rm32, r32
				i.a = modrm(r, rf, 4);
				i.b = reg_op(rf);
				break;
			case 3: // r32, rm32
				i.b = modrm(r, rf, 4);
				i.a = reg_op(rf);
				break;
			case 5: { // eax, imm32
				i.a      = reg_op(EAX);
				int pos  = int(r.at);
				i.b      = imm_op(r.i32(), pos);
				break;
			}
			default:
				throw bad("8-bit arithmetic is not supported");
			}
		} else if (b >= 0x40 && b <= 0x47) {
			i.code = op::INC;
			i.a    = reg_op(b - 0x40);
		} else if (b >= 0x48 && b <= 0x4F) {
			i.code = op::DEC;
			i.a    = reg_op(b - 0x48);
		} else if (b >= 0x50 && b <= 0x57) {
			i.code = op::PUSH;
			i.a    = reg_op(b - 0x50);
		} else if (b >= 0x58 && b <= 0x5F) {
			i.code = op::POP;
			i.a    = reg_op(b - 0x58);
		} else if (b == 0x68) {
			i.code  = op::PUSH;
			int pos = int(r.at);
			i.a     = imm_op(r.i32(), pos);
		} else if (b == 0x6A) {
			i.code = op::PUSH;
			i.a    = imm_op(r.i8());
		} else if (b == 0x69 || b == 0x6B) {
			i.code = op::IMUL;
			i.b    = modrm(r, rf, 4);
			i.a    = reg_op(rf);
			int pos = int(r.at);
			i.c    = (b == 0x69) ? imm_op(r.i32(), pos) : imm_op(r.i8());
		} else if (b >= 0x70 && b <= 0x7F) {
			i.code = op::JCC;
			i.cond = cc(b - 0x70);
			int pos = int(r.at);
			i.a    = imm_op(r.i8());
			i.a.pos = -1;
			(void)pos;
		} else if (b == 0x81 || b == 0x83) {
			i.a    = modrm(r, rf, 4);
			i.code = alu(rf);
			int pos = int(r.at);
			i.b    = (b == 0x81) ? imm_op(r.i32(), pos) : imm_op(r.i8());
		} else if (b == 0x85) {
			i.code = op::TEST;
			i.a    = modrm(r, rf, 4);
			i.b    = reg_op(rf);
		} else if (b == 0x87) {
			i.code = op::XCHG;
			i.a    = modrm(r, rf, 4);
			i.b    = reg_op(rf);
		} else if (b == 0x89) {
			i.code = op::MOV;
			i.a    = modrm(r, rf, 4);
			i.b    = reg_op(rf);
		} else if (b == 0x8B) {
			i.code = op::MOV;
			i.b    = modrm(r, rf, 4);
			i.a    = reg_op(rf);
		} else if (b == 0x8D) {
			i.code = op::LEA;
			i.b    = modrm(r, rf, 4);
			if (i.b.type != operand::kind::mem) {
				throw bad("lea of a register");
			}
			i.a = reg_op(rf);
		} else if (b == 0x90) {
			i.code = op::NOP;
		} else if (b == 0x99) {
			i.code = op::CDQ;
		} else if (b == 0x9E) {
			i.code = op::SAHF;
		} else if (b >= 0xB8 && b <= 0xBF) {
			i.code  = op::MOV;
			i.a     = reg_op(b - 0xB8);
			int pos = int(r.at);
			i.b     = imm_op(r.i32(), pos);
		} else if (b == 0xC1 || b == 0xD1) {
			i.a = modrm(r, rf, 4);
			switch (rf) {
			case 4:
				i.code = op::SHL;
				break;
			case 5:
				i.code = op::SHR;
				break;
			case 7:
				i.code = op::SAR;
				break;
			default:
				throw bad("unsupported shift");
			}
			i.b = imm_op(b == 0xC1 ? int32_t(r.u8() & 31) : 1);
		} else if (b == 0xC2) {
			i.code = op::RET;
			i.a    = imm_op(r.u16());
		} else if (b == 0xC3) {
			i.code = op::RET;
			i.a    = imm_op(-1); // A plain return: back from a Gosub
		} else if (b == 0xC7) {
			i.a = modrm(r, rf, 4);
			if (rf != 0) {
				throw bad("unsupported C7 form");
			}
			i.code  = op::MOV;
			int pos = int(r.at);
			i.b     = imm_op(r.i32(), pos);
		} else if (b == 0xE8 || b == 0xE9) {
			i.code  = (b == 0xE8) ? op::CALL : op::JMP;
			int pos = int(r.at);
			i.a     = imm_op(r.i32(), pos);
		} else if (b == 0xEB) {
			i.code = op::JMP;
			i.a    = imm_op(r.i8());
		} else if (b == 0xF7) {
			i.a = modrm(r, rf, 4);
			switch (rf) {
			case 0: {
				i.code  = op::TEST;
				int pos = int(r.at);
				i.b     = imm_op(r.i32(), pos);
				break;
			}
			case 2:
				i.code = op::NOT;
				break;
			case 3:
				i.code = op::NEG;
				break;
			case 4:
				i.code = op::MUL;
				break;
			case 6:
				i.code = op::DIV;
				break;
			case 7:
				i.code = op::IDIV;
				break;
			default:
				throw bad("unsupported F7 form");
			}
		} else if (b == 0xFF) {
			i.a = modrm(r, rf, 4);
			switch (rf) {
			case 0:
				i.code = op::INC;
				break;
			case 1:
				i.code = op::DEC;
				break;
			case 2:
				i.code = op::CALL;
				break;
			case 4:
				i.code = op::JMP;
				break;
			case 6:
				i.code = op::PUSH;
				break;
			default:
				throw bad("unsupported FF form");
			}
		} else if (b == 0x0F) {
			uint8_t b2 = r.u8();
			if (b2 >= 0x80 && b2 <= 0x8F) {
				i.code  = op::JCC;
				i.cond  = cc(b2 - 0x80);
				int pos = int(r.at);
				i.a     = imm_op(r.i32(), pos);
			} else if (b2 >= 0x90 && b2 <= 0x9F) {
				i.code = op::SETCC;
				i.cond = cc(b2 - 0x90);
				i.a    = modrm(r, rf, 1);
				if (i.a.type != operand::kind::reg) {
					throw bad("setcc to memory");
				}
			} else if (b2 == 0xAF) {
				i.code = op::IMUL;
				i.b    = modrm(r, rf, 4);
				i.a    = reg_op(rf);
			} else if (b2 == 0xB6 || b2 == 0xB7 || b2 == 0xBE || b2 == 0xBF) {
				i.code = (b2 < 0xB8) ? op::MOVZX : op::MOVSX;
				i.b    = modrm(r, rf, (b2 & 1) ? 2 : 1);
				i.a    = reg_op(rf);
			} else {
				throw bad("unsupported two-byte opcode");
			}
		} else if (b >= 0xD8 && b <= 0xDF) {
			uint8_t m = (r.at < code.size()) ? code[r.at] : 0;
			if (m >= 0xC0) {
				r.u8();
				int n = m & 7;
				switch ((uint32_t(b) << 8) | m) {
				default: {
					uint32_t k = (uint32_t(b) << 8) | (m & 0xF8);
					i.fpi      = n;
					if (k == 0xDEC0) {
						i.code = op::FADDP;
					} else if (k == 0xDEC8) {
						i.code = op::FMULP;
					} else if (k == 0xDEE0) {
						i.code = op::FSUBRP;
					} else if (k == 0xDEE8) {
						i.code = op::FSUBP;
					} else if (k == 0xDEF0) {
						i.code = op::FDIVRP;
					} else if (k == 0xDEF8) {
						i.code = op::FDIVP;
					} else if (k == 0xD9C8) {
						i.code = op::FXCH;
					} else if (m == 0xE0 && b == 0xD9) {
						i.code = op::FCHS;
					} else if (m == 0xE1 && b == 0xD9) {
						i.code = op::FABS;
					} else if (m == 0xE8 && b == 0xD9) {
						i.code = op::FLD1;
					} else if (m == 0xEE && b == 0xD9) {
						i.code = op::FLDZ;
					} else if (m == 0xE9 && b == 0xDA) {
						i.code = op::FUCOMPP;
					} else if (m == 0xE0 && b == 0xDF) {
						i.code = op::FNSTSW;
						i.a    = reg_op(EAX, 2);
					} else {
						throw bad("unsupported x87 instruction");
					}
				}
				}
			} else {
				i.b = modrm(r, rf, (b == 0xDD) ? 8 : 4);
				i.a = i.b;
				i.b = operand{};
				if (b == 0xD9 && rf == 0) {
					i.code = op::FLD;
				} else if (b == 0xD9 && rf == 2) {
					i.code = op::FST;
				} else if (b == 0xD9 && rf == 3) {
					i.code = op::FSTP;
				} else if (b == 0xDB && rf == 0) {
					i.code = op::FILD;
				} else if (b == 0xDB && rf == 2) {
					i.code = op::FIST;
				} else if (b == 0xDB && rf == 3) {
					i.code = op::FISTP;
				} else if (b == 0xDD && rf == 0) {
					i.code = op::FLD;
				} else if (b == 0xDD && rf == 3) {
					i.code = op::FSTP;
				} else {
					throw bad("unsupported x87 instruction");
				}
			}
		} else {
			throw bad("unsupported opcode");
		}
		i.size = r.at - address;
		return i;
	}

	char const* name(op o)
	{
		static const char* names[] = { "mov", "movzx", "movsx", "lea", "xchg", "push", "pop", "nop", "add", "or", "adc", "sbb", "and", "sub", "xor", "cmp", "test", "inc", "dec", "neg", "not", "imul", "mul", "idiv", "div", "cdq", "shl", "shr", "sar", "jmp", "jcc", "call", "ret", "setcc", "sahf", "fld", "fild", "fst", "fstp", "fistp", "fist", "fld1", "fldz", "fxch", "faddp", "fsubp", "fsubrp", "fmulp", "fdivp", "fdivrp", "fchs", "fabs", "fucompp", "fnstsw" };
		return names[int(o)];
	}
} // namespace blitz::recompiler::x86
